import base64
from pathlib import Path
import marimo._code_mode as cm

b64_data = """"""

out_p = Path("/marimo/output/student_only_benchmark.json")
out_p.write_bytes(base64.b64decode(b64_data))
print("Wrote benchmark json:", out_p.stat().st_size, "bytes")

async def main():
    async with cm.get_context() as ctx:
        c19 = [c for c in ctx.cells if c.name == "moe_training_result_status"][0]
        ctx.run_cell(c19.id)
        print("Re-ran cell", c19.id)

await main()
